import React from 'react';

const About = () => {
  return (
    <div style={{ padding: '20px' }}>
      <h1>About Page</h1>
      <p>This is a simple React application demonstrating routing with React Router.</p>
      <p>Developers:
        <ul>
          <li>John Doe</li>
          <li>Jane Smith</li>
          <li>Alex Johnson</li>
        </ul>
      </p>
      <p>Version: 1.0.0</p>
      <p>License: MIT</p>
      <p>For more information, visit our <a href="#"target="_blank" rel="noopener noreferrer">GitHub repository</a>.</p>
      <p>Contact us at: <a href="mailto:andrewvista2005@gmail.com">EMAIL</a>
      </p>
    </div>
  );
};

export default About;
